function updateVisibility(){DATA.systems.forEach(s=>{let cat=['hazard','uncertain'].includes(s.kind)?'hazard':['context','neutral'].includes(s.kind)?'context':'federation';const visible=flags[cat]&&(!$('majorOnly').checked||s.worlds.length);$('node-'+s.id).classList.toggle('hidden-node',!visible);$('node-'+s.id).querySelector('.star-hit').setAttribute('tabindex',visible?'0':'-1')});document.querySelectorAll('.node-label').forEach(e=>e.style.display=$('labels').checked?'':'none');$('regionLayer').classList.toggle('borders-hidden',!$('borders').checked);$('hexLayer').style.display=$('hexes').checked?'':'none';scaleLabels()}
